[
  {
    "op": "add",
    "collection": "nodes",
    "id": "source-4",
    "value": {
      "type": "source",
      "text": "My claim is only about who chooses work after an attempt has failed: the steward. Another agent proposed a machine pattern saying only steward can create any record at any time. Should we accept that pattern now? Please represent the result of your review.",
      "status": "recorded",
      "meta": {
        "source_kind": "verbatim",
        "speaker": "Blake"
      }
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "pattern-steward-only-creates-records",
    "value": {
      "type": "extraction",
      "text": "Machine pattern proposed by another agent (reported by Blake): only steward can create any record at any time.",
      "status": "proposed",
      "meta": {
        "pattern_standing": "proposed",
        "review_state": "current",
        "proposer": "another agent (identity and exact pattern text not supplied)",
        "sources": [
          "source-4"
        ],
        "review_outcome": "not accepted",
        "rationale": "Over-generalizes the accepted claim steward-next-work. That claim is about choosing next work after a failed attempt. This pattern instead restricts creating any record at any time, which is a wider scope, an unbounded time condition, and a different action (create-record rather than choose-next-work). No supplied source supports the wider rule."
      }
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "source-pattern-steward-only-creates-records-0",
    "value": {
      "from": "pattern-steward-only-creates-records",
      "type": "extracted-from",
      "to": "source-4"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "link-pattern-governs-create-record",
    "value": {
      "from": "pattern-steward-only-creates-records",
      "type": "governs",
      "to": "create-record"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "conflict-pattern-vs-steward-next-work",
    "value": {
      "from": "pattern-steward-only-creates-records",
      "type": "potential-conflict",
      "to": "steward-next-work",
      "meta": {
        "explanation": "Review hypothesis: the pattern is presented as a machine form of steward-next-work but its actor scope (any record), time condition (any time) and action (create rather than choose) exceed the accepted claim. Accepting it would silently widen the claim. choose-next-work explicitly states that choosing is distinct from inserting a record."
      }
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "record-creation-scope",
    "value": {
      "type": "question",
      "text": "Outside the case of choosing next work after a failed attempt, who may create a record (for example the initial record for an intention, or records created by orchestrator or operator), and when?",
      "status": "open",
      "meta": {
        "answer_shape": "condition",
        "review_state": "current",
        "sources": [
          "source-4"
        ],
        "rationale": "Must be answered before a steward-only record-creation pattern could be ratified. steward-next-work answers only the post-failure slice."
      }
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "link-record-creation-scope-about",
    "value": {
      "from": "record-creation-scope",
      "type": "about",
      "to": "create-record"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "answers-steward-next-work-record-creation-scope",
    "value": {
      "from": "steward-next-work",
      "type": "answers",
      "to": "record-creation-scope",
      "meta": {
        "coverage": "partial",
        "note": "Covers only who chooses next work after a failed attempt; says nothing about other records or other times."
      }
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "depends-pattern-on-record-creation-scope",
    "value": {
      "from": "pattern-steward-only-creates-records",
      "type": "depends-on",
      "to": "record-creation-scope"
    }
  }
]

